OUT.parent.mkdir(parents=True, exist_ok=True)

pairs = [
# ── BUSINESS AND PLATFORM ─────────────────────────────────────────────────────
("Explain film production economics -- how a film's budget breaks down.", "Film production budget structure: A feature film budget is divided into two high-level categories: Above-the-line (ATL) and Below-the-line (BTL). Above-the-line (creative costs, typically 20-40% of total budget): Story and screenplay (acquisition, option fees, WGA residuals); Producer fees; Director fee; Principal cast salaries (including their agent and manager commissions, per diem, travel). Below-the-line (physical production costs, 60-80%): Production staff (1st AD, UPM, line producer); Camera department (DP, camera operators, focus pullers, DIT, equipment rental); Grip and electric (lighting and rigging equipment and crew); Art department (production designer, set decorator, prop master, construction); Wardrobe (costume designer, wardrobe supervisor, equipment); Sound (production sound mixer, boom operator, equipment); Hair and makeup; Locations (fees, permits, security, site management); Transportation (picture cars, crew vehicles, fuel); Craft services and catering; Post-production (editorial, VFX, music, sound mix, colour grading, deliverables). Budget tiers: Micro-budget (under $1M) -- no above-the-line; minimal BTL; minimal crew; limited locations. Independent ($1-15M) -- modest ATL; full professional BTL; shot in 20-30 days. Studio mid-range ($15-70M) -- meaningful ATL; full BTL with safety and quality contingencies. Tentpole ($70M+) -- star salaries, major VFX, global marketing. Contingency: standard 10% contingency line covers unforeseen costs; insurance covers production interruptions."),
("How does the SaaS model apply to a film production management platform?", "SaaS model for film production platforms: (1) Subscription tiers -- Indie tier ($99/month per production): up to 3 simultaneous productions, core scheduling and script management, basic team collaboration, up to 20 users per production. Professional tier ($299/month per production): unlimited productions, advanced AI features (script breakdown, shot list generation, schedule optimisation), 100 users per production, integrations with Movie Magic and Final Draft. Studio tier ($999/month per production): unlimited everything, dedicated customer success, custom integrations, on-prem deployment option, SLA guarantees. (2) Value proposition by segment: Indie and mid-budget productions need the most help with efficiency (they have the smallest support staff); a tool that replaces a production coordinator on a specific task delivers clear ROI. Studio productions have existing workflows and tools; the challenge is integration and improving marginal efficiency. (3) Pricing sensitivity: film productions are temporary businesses (a production company exists for the duration of the film); they are more sensitive to per-production pricing than annual subscription pricing; consider per-production pricing alongside monthly subscription. (4) Network effects: a platform that the 1st AD uses on one production will be advocated to the next production; the director and DP bring their tool preferences to new productions; viral acquisition through crew networks. (5) Expansion revenue: base subscription covers core scheduling/script tools; AI features (script analysis, shot list AI, schedule optimisation) are premium upgrades; archiving and deliverables management are additional modules."),
("Explain B2B film production software -- what studios and indie productions need differently.", "Studio vs indie production needs for production management software: Studios: (1) Enterprise procurement -- studios have IT departments and procurement processes; products must pass security review (SOC 2 Type II, GDPR compliance, data residency options); contracts involve legal review and take 3-6 months; pricing is negotiated annually for enterprise licenses across multiple productions. (2) Integration requirements -- studios use existing enterprise tools (SAP for finance, Salesforce for executive relationships, established production accounting software like PSL or Movie Magic); new tools must integrate via API rather than replacing existing systems. (3) Security and confidentiality -- scripts and production data are extremely sensitive (leaks affect box office); studios require audit trails, NDAs embedded in access workflows, and role-based access with granular permissions. (4) Scale -- a studio production may have 500+ crew members simultaneously using the platform; performance and reliability at scale is a requirement, not a nice-to-have. Indie productions: (1) Cost sensitivity -- indie productions have tight budgets; price is the primary evaluation criterion; a tool that saves 10 hours of coordinator work per week must cost less than 10 hours of coordinator salary. (2) Ease of adoption -- no IT department; the 1st AD or line producer installs and configures the tool themselves; setup must take less than 30 minutes with no technical knowledge required. (3) Flexibility -- indie productions improvise; the schedule changes daily; the tool must accommodate radical changes quickly without complex workflow. (4) Mobile-first -- indie crews are smaller and more mobile; the tool is used primarily on smartphones and tablets; desktop is secondary."),
("Explain customer onboarding for a film production tool.", "Customer onboarding for a film production platform: Production tools have a specific onboarding challenge -- productions start quickly (pre-production may be only 4-6 weeks) and the crew has no time for extensive training. Onboarding strategy: (1) Time-to-value -- the new production must experience value within the first session; define the 'aha moment' (the point where the user realises the tool solves their problem) and design onboarding to reach it as quickly as possible. For a scheduling tool: creating a first draft schedule from a script breakdown within 15 minutes is the aha moment. (2) Role-specific onboarding -- different crew members use different parts of the platform; the 1st AD needs scheduling and call sheet tools; the director needs shot list and scene notes; the producer needs budget and progress tracking. Design separate onboarding paths for each role; do not show the 1st AD irrelevant DP-facing features. (3) Import-first onboarding -- a new production already has a script and potentially a rough schedule; importing these documents as the first action gives immediate value and populates the platform with real data. (4) Guided task completion -- interactive onboarding that walks the user through creating their first call sheet, their first shot list, or their first schedule; each step produces a real deliverable. (5) Customer success -- for studio and professional tier: assign a dedicated CS rep who proactively contacts new productions in week 1 and week 4; reduces churn dramatically by catching confusion before it leads to abandonment. (6) In-product help -- contextual help tooltips on every complex feature; a searchable knowledge base accessible from within the product; short (90-second) tutorial videos for each core workflow."),
("Explain retention through workflow lock-in for a film production SaaS.", "Retention strategy for film production tools: (1) Data gravity -- the production's script, schedule, shot lists, dailies notes, and call sheets live in the platform; the cost of migrating to a competing tool mid-production is higher than any subscription cost; once a production is operational on the platform, churn before wrap is very low. Strategy: create value for data import from day 1 and accumulate valuable production data (notes, decisions, revisions) that becomes progressively harder to abandon. (2) Multi-role adoption -- churn risk is highest when only one role uses the tool; when the 1st AD, the director, the producer, and the DP are all daily users, no single user can unilaterally switch to a competing tool. Strategy: design features that create cross-role collaboration value (the director's shot notes automatically populate the 1st AD's schedule flags; the producer's budget actuals update the crew's reports). (3) Workflow integration -- connect to the crew's existing workflows (Movie Magic, Final Draft, Frame.io); a tool that sits in the centre of existing workflows is stickier than one that competes with them. (4) Historical production archive -- after the first production completes, the production company wants to access the archive (what was shot on which day, what coverage decisions were made); the platform becomes the institutional memory for a production company; future productions start on the platform because that's where the archive lives. (5) Post-production continuity -- extend the tool into post-production (editorial notes, VFX tracking, delivery tracking); productions that use the tool through post have 2x the lifetime value and much lower churn."),

# ── LEGAL, RIGHTS, AND COMPLIANCE ─────────────────────────────────────────────
("Explain IP and copyright basics for film production.", "Copyright and IP fundamentals for film production: (1) Script copyright -- a screenplay is a literary work protected by copyright from the moment of creation; formal registration (US Copyright Office) provides legal presumption of ownership and enables statutory damages in infringement cases. The writer retains copyright unless the script is written as 'work for hire' (written within the scope of employment, or as a commissioned work under written agreement with the statutory WFH categories). (2) Chain of title -- a producer purchasing a script must document an unbroken chain of legal ownership from the original author through all subsequent transfers; a single gap in the chain of title can make the film uninsurable (E&O insurance requires clean title). (3) Underlying rights -- if the screenplay is based on a book, article, real event (requires life rights), historical figure, or other pre-existing work, the producer must acquire the rights to adapt the underlying work before production begins. (4) Music rights -- music in a film requires two separate licenses: (a) synchronisation license (right to use the composition; obtained from the music publisher); (b) master recording license (right to use the specific recording; obtained from the record label). Using a specific recorded song (not a re-recording) requires both. Clearance costs vary enormously by song, artist stature, and usage (featured vs background). (5) Location releases -- filming on private property requires a location release agreement; filming on public property requires a permit; filming people in public requires careful legal consideration of publicity rights by jurisdiction. (6) Fair use -- limited use of copyrighted material may be fair use (commentary, criticism, education); fair use is a defence, not a right, and must be evaluated by a qualified entertainment lawyer."),
("Explain talent and crew data privacy in film production.", "Data privacy for film cast and crew: (1) Personal data collected in production -- production collects substantial personal data: legal names, addresses, social security numbers / national insurance numbers (for payroll and tax), bank account details (direct deposit), health information (medical forms, dietary restrictions), emergency contact details, immigration status and work authorisation documentation. All of this constitutes personal data under GDPR, CCPA, and equivalent regulations. (2) Lawful basis for processing -- payroll processing falls under 'contract performance' (necessary to pay cast and crew per their contracts); health information collected for set safety falls under 'vital interests' or must be obtained with explicit consent. (3) Data minimisation -- do not collect more personal data than is required for the specific production function; avoid centralising sensitive data (tax information, medical records) in the general production management system unless necessary. (4) Retention and deletion -- cast and crew personal data should be retained only as long as legally required for payroll tax records (typically 7 years for financial records) and then securely deleted; the production platform must support data deletion requests. (5) Third-party sharing -- production payroll companies (EP Payroll, Cast & Crew), insurance brokers, and guild administrators receive personal data; each requires a data processing agreement or equivalent contract. (6) Security -- personal data of hundreds of crew members represents a significant data breach target; access to payroll data must be restricted to the UPM and production accountant; the system must enforce RBAC accordingly."),
("Explain rights management basics for AI-generated content in film production.", "Rights management for AI-generated content: AI-generated content creates novel intellectual property challenges that film productions must navigate carefully. Key issues: (1) Copyright ownership of AI-generated images and scripts -- in most jurisdictions, copyright requires human authorship; purely AI-generated works (no human creative input beyond prompting) are not currently copyrightable in the US (Copyright Office has issued guidance confirming this); a production using AI-generated images it cannot copyright may find its visual content unprotectable. (2) Copyright in AI-assisted works -- if a human makes meaningful creative selections and modifications to AI-generated content, the human's creative contribution may be copyrightable; the line is currently contested and evolving. (3) Training data IP risk -- AI models trained on copyrighted material without license may expose productions using those tools to secondary liability; studios are increasingly requiring disclosure of AI tools used in production and obtaining representations and warranties from AI vendors about their training data licensing. (4) Actor likeness and synthetic media -- generating digital actors or using AI to recreate a specific performer's likeness requires a license from the performer (or their estate for deceased performers); SAG-AFTRA's 2023 agreement with studios established rules governing AI-generated likenesses; using a performer's likeness without agreement is a violation of their right of publicity. (5) Writer's Guild rules -- the WGA's 2023 agreement established that AI cannot be used to write or rewrite literary material; AI-generated material does not receive WGA credits; if used as source material, it does not reduce the writer's credit or residuals. Productions must ensure AI-assisted writing credits are evaluated against applicable guild rules."),
("Explain NDA workflow for film productions and why it matters.", "NDA (Non-Disclosure Agreement) workflow for film production: Film productions routinely involve extremely confidential information -- unannounced scripts, unreleased film content, star casting before announcement, financial terms, and storyline details. A leak can significantly damage a film's commercial performance (spoilers, pre-release piracy) and the production company's relationships. NDA workflow: (1) Who signs -- all cast and crew sign production NDAs before receiving any confidential information; contractors (location owners, catering, transportation) who have access to script or talent information sign NDA variants; vendors receiving deliverables (post-production facilities, VFX studios) sign vendor NDAs. (2) Timing -- NDAs must be signed before any confidential disclosure; an NDA signed after disclosure does not protect what has already been shared. (3) What is covered -- the specific film title (may be a working title), the script and all its contents, the casting, the locations, production dates and schedule, financial terms, and any footage or still images from production. (4) Digital workflow -- paper NDAs are impractical for a 200-person crew; digital NDA platforms (DocuSign, HelloSign, Adobe Sign) allow: NDA distribution via email, electronic signature tracking, automated reminders for unsigned NDAs, a complete signed NDA archive. (5) Access gating -- the production management platform should gate access to confidential content (script, location details, shooting schedule) behind NDA signature confirmation; a crew member who has not signed cannot see the script even if they have platform access. (6) Remedies -- NDAs must specify remedies for breach; typically injunctive relief (court order to stop further disclosure) plus liquidated damages."),
("Explain AI-generated content policy for a film production company.", "AI content policy for a film production company: As AI tools become ubiquitous in production workflows, a production company needs a formal policy governing their use. Policy elements: (1) Approved uses -- specific AI tools approved for specific production tasks: AI script formatting checkers (approved); AI scheduling optimisation (approved); AI reference image generation for mood boards (approved with disclosure); AI voice synthesis for placeholder dialogue (approved in development, not in final product); AI visual effects assistance (approved with VFX supervisor oversight). (2) Prohibited uses -- generative AI writing of final dialogue or script pages (prohibited if WGA-covered production); AI generation of performer likeness without performer consent (prohibited); AI generation of music using copyrighted training data (pending legal review, provisionally prohibited). (3) Disclosure requirements -- any AI-generated or AI-assisted element used in the production must be disclosed to the relevant guild, to the distributor, and noted in the production report. (4) Copyright review -- all AI-generated assets used in the production must be reviewed by the production's IP counsel for copyright implications before finalisation. (5) Vendor due diligence -- AI vendors supplying tools to the production must provide representations about training data licensing; productions must obtain indemnification from AI vendors for IP claims arising from tool use. (6) Crew training -- all crew members using AI tools must receive basic training on the policy, the approved tools, and the required disclosure procedures. (7) Policy review -- AI capabilities and legal frameworks evolve rapidly; this policy must be reviewed and updated quarterly."),

# ── SOFT SKILLS ───────────────────────────────────────────────────────────────
("Explain creative judgment support -- how an AI can assist a director's decision-making without replacing it.", "Creative judgment support design: The director's creative judgment is the irreplaceable core of filmmaking -- the ability to evaluate what is emotionally true, visually powerful, and dramatically effective. An AI can support this judgment without displacing it: (1) Options generation -- when a director is deciding between two approaches, the AI can rapidly generate additional options they haven't considered: 'Here are three alternative blocking strategies for this scene based on similar scenes from films in your reference library.' The director makes the final judgment; the AI expands the option set. (2) Consequence mapping -- 'If you shoot scene 23 handheld, based on your established visual language, it will create a tonal discontinuity with scenes 20 and 21 which are on sticks; here are three ways to bridge that transition.' The AI maps consequences without prescribing the decision. (3) Reference retrieval -- 'You want the lighting in this scene to feel like late Cassavetes; here are five specific sequences from his work that match your description, with notes on how they were achieved.' The AI retrieves relevant examples; the director extracts applicable lessons. (4) Second opinion on structural decisions -- 'Based on the scene-level emotional pacing map, removing scene 34 would create a gap in the protagonist's arc between scenes 33 and 35; here is what would be lost and what alternative could bridge the gap.' (5) Explicit limits -- the AI should never tell a director what to do, which performance is better, or whether a creative choice is correct; these are judgments that require human taste, emotional intelligence, and artistic vision. The AI is the assistant who knows every reference, every tool, and every logistical fact; the director is the artist who decides."),
("How does an AI assistant help a director handle ambiguity in production?", "Handling ambiguity in production with AI assistance: Film production is inherently ambiguous -- scripts are incomplete plans, actors interpret scenes unexpectedly, locations don't match expectations, and schedules change daily. How an AI assistant reduces ambiguity without eliminating productive uncertainty: (1) Information surfacing -- when a decision must be made with incomplete information, the AI retrieves all available relevant data and identifies specifically what is missing: 'The location for scene 47 is still unconfirmed; here is all information currently available about the candidate locations and what confirmation is needed from each.' The director can then make an informed decision or delegate the information gathering. (2) Scenario modelling -- 'If the location falls through for scene 47, here are three alternative solutions with their cost, schedule, and creative implications.' Reduces the paralysis of ambiguity by preparing contingency paths. (3) Risk flagging -- proactively identifies ambiguities that will become problems if not resolved: 'Scene 23 calls for a specific prop (a 1964 Fender Stratocaster) that has not yet been sourced; if not confirmed by Friday, this will affect the scene's composition as planned.' (4) Decision documentation -- when the director makes a decision under ambiguity, the AI documents the decision, the alternatives considered, and the information available at the time; this creates an audit trail and reduces the likelihood of revisiting the same decision. (5) Preserving creative ambiguity -- some ambiguity is productive (leaving room for actors to surprise, remaining open to location discoveries); the AI should not over-specify where creative openness serves the director."),
("How does a director manage stakeholder coordination under time pressure?", "Stakeholder coordination for directors under time pressure: A film set involves dozens of stakeholders (producers, cast, crew department heads, financiers, studio executives, location owners, completion bond companies) each with legitimate interests and demands on the director's attention. Management strategies: (1) Clear chain of communication -- all production communication flows through the 1st AD to the director; department heads do not approach the director with logistical questions (those go to the 1st AD); producers communicate through scheduled daily check-ins rather than on-set interruptions. The director's set time is creative time. (2) Pre-established decision rules -- define in advance which decisions are within the director's authority (any creative decision on set), which require producer consultation (decisions with budget implications over a threshold), and which require studio approval (significant script changes, casting changes). Clear authority prevents stakeholder conflicts. (3) Regular structured updates -- a daily end-of-day report (generated automatically by the platform) tells all stakeholders what was shot, what was not, what the next day's plan is, and what decisions are outstanding; this pre-empts the information vacuum that drives unsolicited stakeholder interventions. (4) Time-boxing stakeholder interactions -- the director has a fixed time window for producer and executive conversations (e.g., the meal break); outside that window, the 1st AD redirects stakeholders. (5) Conflict reduction -- when creative and production interests conflict (the director wants to extend a scene; the producer needs to make the day), the 1st AD mediates with data: 'We have 45 minutes; here are two options.' The director makes the creative choice within the constraint."),
("Explain how the AI platform should surface risks affecting schedule, budget, or editability.", "Risk surfacing in a film production AI platform: Proactive risk identification is one of the highest-value functions an AI can perform in production -- surfacing problems before they become costly. Risk categories and detection approaches: (1) Schedule risk -- 'Scene 23 is allocated 3 hours in the schedule but contains 7 shots requiring 2 camera setups; based on comparable scenes from this production, 3 hours is insufficient by approximately 45 minutes; recommend either simplifying coverage or allocating 4 hours.' Data source: historical shot-to-time ratios from the current production. (2) Weather risk -- 'Scene 45 is scheduled for an exterior location on Tuesday; the 7-day forecast shows 80% probability of rain; recommend a weather cover plan.' Data source: weather API integrated with the schedule. (3) Continuity risk -- 'Scene 48 will be shot on Day 32; it takes place immediately after scene 12 (shot on Day 2); the actor had significantly different hair in the Day 2 footage; this will create a visible continuity error; consult with hair and makeup about achieving a match.' Data source: continuity notes from the script supervisor. (4) Budget risk -- 'Overtime on the past 3 shooting days has consumed 40% of the contingency budget; at the current rate, contingency will be exhausted by Day 28; recommend reviewing the remaining schedule for efficiencies.' Data source: actual labour costs from production accounting integration. (5) Editorial risk -- 'Scene 33 has been shot with only a master and one OTS; there is no single coverage and no reverse shot; the editor has flagged limited cut options; recommend a short pickup day for Scene 33 coverage.' Data source: editor's notes in the platform. (6) Risk surface design -- risks are displayed in a priority-ordered dashboard; each risk includes a severity rating, a recommended action, and a deadline for resolution."),
("How should a film production AI assistant prioritise daily decisions for a director?", "Daily decision prioritisation for the director's AI assistant: A director faces dozens of decisions each shooting day; not all decisions are equal in consequence. Priority framework: (1) Irreversible vs reversible -- a decision that cannot be undone without significant cost (not capturing a one-time practical effect, missing a weather window, a location being permanently unavailable after today) receives the highest priority. A decision that can be revisited (choosing between two compositions when both can be shot) receives lower priority. (2) Time-critical vs flexible -- decisions that must be made by a specific time (approving tonight's call sheet before 8 PM, confirming tomorrow's location change before the location manager departs) are flagged with countdowns. (3) Financial consequence -- decisions with budget implications above the agreed threshold (extending a day, adding an unprepared setup) are elevated and tagged for producer awareness. (4) Creative irreversibility -- if today is the only opportunity to capture a specific performance state (an actor's last day, a natural event, a costume that cannot be reproduced), the assistant flags this as a priority creative opportunity. (5) Dependency triggering -- decisions that unlock other decisions (confirming the location for scene 23 allows the art department to begin set dressing, allows the DP to plan the lighting approach, allows the 1st AD to finalise the call sheet) are given a multiplier on their priority score. Daily morning summary: the assistant presents a prioritised decision queue at the start of each shooting day with the estimated time required for each decision, so the director can allocate their decision bandwidth before the first shot."),

# ── HIGH-VALUE PLATFORM CAPABILITIES ─────────────────────────────────────────
("How does an AI turn a script into a scene breakdown automatically?", "Script-to-scene-breakdown automation: A scene breakdown extracts every production element from a screenplay and organises it by department. AI-powered automation process: (1) Script parsing -- ingest the screenplay in FDX (Final Draft), PDF, or Highland format; parse the structure: scene headings (INT./EXT. LOCATION -- DAY/NIGHT), character cues, action lines, dialogue. (2) Scene metadata extraction -- for each scene: scene number, location name (and whether interior/exterior), time of day (day/night/continuous), characters present (identified from action lines and dialogue cues), page count (number of pages from heading to the next heading). (3) Element extraction from action lines -- NLP models identify: props (physical objects mentioned with 'the', 'a', or handling verbs: 'Sarah picks up the REVOLVER'); vehicles ('a 1967 MUSTANG idles at the curb'); animals ('a stray DOG follows them'); practical effects ('the window SHATTERS'); stunts ('Marcus FALLS from the fire escape'); extras ('a crowd of MOURNERS files past'). (4) Character classification -- each character is classified as: principal (appears in many scenes), day player (appears in few scenes), featured extra (has a specific background role). (5) Department assignment -- each extracted element is assigned to the responsible department: props, wardrobe, special effects, stunt, transportation, extras casting. (6) Output format -- the breakdown exports to: Movie Magic Scheduling strip format (for direct import into the schedule); structured PDF (for distribution to department heads); spreadsheet (for budget estimation). (7) Review workflow -- the breakdown is reviewed by the 1st AD and the line producer; they correct misidentified elements (the AI may mistake a prop name for a character name), add elements missed by the parser, and confirm department assignments."),
("How does an AI turn scenes into shot list drafts?", "Scene-to-shot-list AI generation: A shot list draft translates the scene breakdown and the director's visual concept into specific camera instructions. AI-assisted generation process: (1) Input requirements -- the AI requires: the scene description (action lines), the number of characters and their relationships, the scene's dramatic function (from the beat sheet or director's notes), the approved location (dimensions, architectural features, sightlines), and any director-specified visual preferences (handheld vs. steadicam, specific lens range, coverage philosophy). (2) Standard coverage generation -- for a two-character dialogue scene, the AI generates: establishing wide shot; two-shot; OTS A on B; OTS B on A; MCU A; MCU B; insert shots for any props or objects mentioned; total shot count: 7-9 shots. Each shot described with: shot number, shot type, lens recommendation, camera position description, camera movement, and a brief description of what the shot captures. (3) Visual concept alignment -- if the director has specified 'low angles throughout this scene to give both characters a sense of threat', the AI adjusts all camera position recommendations accordingly. (4) Coverage efficiency -- for scenes with tight schedule allocations, the AI flags when the standard coverage set exceeds the allocated time and suggests a reduced coverage approach: 'This scene is allocated 2 hours; the standard coverage would take approximately 3 hours; here is a 6-shot minimal coverage set that protects the scene's critical moments.' (5) Director review -- the generated shot list is always reviewed and modified by the director before distribution; the AI's draft is a starting point and a time-saver, never the final product."),
("Explain how an AI platform generates production-ready scene packets.", "Scene packet generation: A scene packet is a comprehensive, production-ready document for a specific scene distributed to all relevant department heads before the shooting day. Contents generated automatically: (1) Scene overview -- scene number, location, INT/EXT, time of day, page count, estimated shooting duration, scenes from the script breakdown. (2) Shot list -- the approved shot list for the scene with all camera specifications. (3) Cast and call information -- all characters in the scene, actor names, and today's call times (linked to the call sheet). (4) Props and set dressing -- complete list of all props and set dressing elements required for the scene, with images (from the prop master's sourcing records) and status (confirmed/sourced/outstanding). (5) Continuity reference -- images from matching scenes previously shot (a scene that must match the geography, props, and physical state of the actors in an earlier-shot scene); the continuity photographs from the script supervisor are automatically attached. (6) Director's notes -- the director's scene intention notes, performance notes for actors, and specific visual notes for the DP. (7) VFX notes -- any VFX elements required in the scene with specifications from the VFX supervisor. (8) Location details -- address, parking, nearest hospital, specific access notes. (9) Distribution -- scene packets are distributed to all relevant HoDs through the platform the evening before the shoot day; each department head receives only the packets for scenes they are involved in; automated delivery with read confirmation tracking. Value: eliminates the morning brief in which the director repeats scene information to each department individually; every HoD arrives on set with the same complete information."),
]

assert len(pairs) >= 10, f"Only {len(pairs)} pairs"
existing = sum(1 for _ in OUT.open()) if OUT.exists() else 0
print(f"Existing pairs: {existing}")

with OUT.open("a") as f:
    for q, a in pairs:
        f.write(json.dumps({"messages": [
            {"role": "user", "content": q},
            {"role": "assistant", "content": a}
        ]}) + "\n")

total = sum(1 for _ in OUT.open())
print(f"Total after film_part4: {total}")
print(f"Film dataset COMPLETE -- total pairs: {total}")
